def top_k(lst, k):
    def sort_list(l):
        l = l[:]
        for i in range(len(l)):
            for j in range(len(l) - i - 1):
                if l[j] < l[j + 1]:
                    l[j], l[j + 1] = l[j + 1], l[j]
        return l

    a = sort_list(lst)
    return a[0:k]
